                            "raw_name = '{name}'.strip()\n"
                            "description = '{description}'.strip()\n"
                            "desc = description.lower()\n"
                            "\n"
                            "# --- Match description to template ---\n"
                            "template = 'generic'\n"
                            "vex_code = ''\n"
