                            "'    n += snoise(@P * f + @Time * "
                            "chf(\"speed\")) * a;\\n'"
                            "'    f *= 2.0; a *= 0.5;\\n'"
                            "'}}\\n'"
                            "'@P += @N * n * amp * chf(\"blend\");\\n')\n"
                            "    parms = [\n"
                            "        ('amplitude', 'Amplitude', "
                            "'float', 0.5),\n"
                            "        ('frequency', 'Frequency', "
                            "'float', 2.0),\n"
                            "        ('octaves', 'Octaves', 'int', 4),\n"
                            "        ('speed', 'Speed', 'float', 0.0),\n"
                            "        ('blend', 'Blend', 'float', 1.0),\n"
                            "    ]\n"
                            "\n"
                            "elif any(w in desc for w in "
                            "['color', 'paint', 'gradient', 'ramp', "
                            "'visualize']):\n"
                            "    template = 'color'\n"
