                            "'float t = fit(@P[axis], bmin[axis], "
                            "bmax[axis], 0, 1);\\n'"
                            "'vector ca = chv(\"color_a\");\\n'"
                            "'vector cb = chv(\"color_b\");\\n'"
                            "'@Cd = lerp(ca, cb, "
                            "chramp(\"gradient\", t));\\n')\n"
                            "    parms = [\n"
                            "        ('axis', 'Axis (0=X 1=Y 2=Z)', "
                            "'int', 1),\n"
                            "        ('color_a', 'Color A', "
