                            "    if not raw_name: raw_name = 'mask_tool'\n"
                            "    vex_code = ("
                            "'// Proximity-based point mask\\n'"
                            "'vector center = chv(\"center\");\\n'"
                            "'float rad = chf(\"radius\");\\n'"
                            "'float d = distance(@P, center);\\n'"
                            "'f@mask = 1.0 - smooth(rad * 0.5, "
                            "rad, d);\\n'"
                            "'if (chi(\"invert\")) "
                            "f@mask = 1.0 - f@mask;\\n'"
